  1→import Database from "better-sqlite3";
  2→import path from "node:path";
  3→
  4→const DB_PATH = path.join(process.cwd(), "data", "recruiting.db");
  5→const db = new Database(DB_PATH);
  6→db.pragma("journal_mode = WAL");
  7→db.pragma("foreign_keys = ON");
  8→
  9→// 1. permissions 테이블 생성
 10→db.exec(`
 11→  CREATE TABLE IF NOT EXISTS permissions (
 12→    id INTEGER PRIMARY KEY AUTOINCREMENT,
 13→    role TEXT NOT NULL,
 14→    resource TEXT NOT NULL,
 15→    action TEXT NOT NULL,
 16→    allowed INTEGER NOT NULL DEFAULT 0,
 17→    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
 18→    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
 19→    UNIQUE(role, resource, action)
 20→  );
 21→`);
 22→
 23→console.log("1. permissions 테이블 생성 완료");
 24→
 25→// 2. users 테이블 CHECK 제약 제거 (테이블 재생성) — VIP 값을 쓰려면 먼저 CHECK 제거 필요
 26→const tableInfo = db
 27→  .prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name='users'")
 28→  .get() as { sql: string } | undefined;
 29→
 30→if (tableInfo?.sql?.includes("CHECK")) {
 31→  // foreign_keys를 일시적으로 끄고 테이블을 재생성
 32→  db.pragma("foreign_keys = OFF");
 33→  db.exec(`
 34→    ALTER TABLE users RENAME TO users_old;
 35→    CREATE TABLE users (
 36→      id INTEGER PRIMARY KEY AUTOINCREMENT,
 37→      username TEXT NOT NULL UNIQUE,
 38→      password TEXT NOT NULL,
 39→      role TEXT NOT NULL,
 40→      department_code TEXT,
 41→      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
 42→      updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
 43→      FOREIGN KEY (department_code) REFERENCES departments (dept_code)
 44→    );
 45→    INSERT INTO users SELECT * FROM users_old;
 46→    DROP TABLE users_old;
 47→  `);
 48→  db.pragma("foreign_keys = ON");
 49→  console.log("2. users 테이블 CHECK 제약 제거 완료");
 50→} else {
 51→  console.log("2. users 테이블에 CHECK 제약 없음, 건너뜀");
 52→}
 53→
 54→// 3. SUPER_ADMIN → VIP 마이그레이션
 55→db.exec(`UPDATE users SET role = 'VIP' WHERE role = 'SUPER_ADMIN';`);
 56→console.log("3. SUPER_ADMIN → VIP 마이그레이션 완료");
 57→
 58→// 4. 시드 권한 데이터
 59→const ACTIONS = ["view", "edit", "delete", "export", "import"];
 60→
 61→const insertPerm = db.prepare(
 62→  "INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES (?, ?, ?, ?)"
 63→);
 64→
 65→const seedAll = db.transaction(() => {
 66→  // VIP: 와일드카드 전체 허용
 67→  for (const action of ACTIONS) {
 68→    insertPerm.run("VIP", "*", action, 1);
 69→  }
 70→
 71→  // ADMIN 권한
 72→  const adminPerms: Record<string, Record<string, number>> = {
 73→    "dashboard.summary": { view: 1, edit: 1, delete: 0, export: 1, import: 1 },
 74→    "dashboard.allocation": { view: 1, edit: 1, delete: 0, export: 1, import: 1 },
 75→    "dashboard.progress": { view: 1, edit: 1, delete: 0, export: 1, import: 1 },
 76→    candidates: { view: 1, edit: 1, delete: 1, export: 1, import: 0 },
 77→    procedures: { view: 1, edit: 1, delete: 0, export: 1, import: 0 },
 78→    actions: { view: 1, edit: 1, delete: 0, export: 0, import: 0 },
 79→    "admin.data-sheet": { view: 1, edit: 1, delete: 1, export: 1, import: 1 },
 80→    "admin.workflow": { view: 1, edit: 1, delete: 1, export: 1, import: 1 },
 81→    "system.users": { view: 1, edit: 1, delete: 1, export: 0, import: 0 },
 82→    "system.permissions": { view: 0, edit: 0, delete: 0, export: 0, import: 0 },
 83→    etc: { view: 1, edit: 1, delete: 0, export: 0, import: 0 },
 84→  };
 85→  for (const [resource, actions] of Object.entries(adminPerms)) {
 86→    for (const [action, allowed] of Object.entries(actions)) {
 87→      insertPerm.run("ADMIN", resource, action, allowed);
 88→    }
 89→  }
 90→
 91→  // DEAN 권한
 92→  const deanPerms: Record<string, Record<string, number>> = {
 93→    "dashboard.summary": { view: 1, edit: 0, delete: 0, export: 1, import: 0 },
 94→    "dashboard.allocation": { view: 0, edit: 0, delete: 0, export: 0, import: 0 },
 95→    "dashboard.progress": { view: 1, edit: 0, delete: 0, export: 0, import: 0 },
 96→    candidates: { view: 1, edit: 1, delete: 0, export: 1, import: 0 },
 97→    procedures: { view: 1, edit: 0, delete: 0, export: 0, import: 0 },
 98→    actions: { view: 1, edit: 1, delete: 0, export: 0, import: 0 },
 99→    "admin.data-sheet": { view: 0, edit: 0, delete: 0, export: 0, import: 0 },
100→    "admin.workflow": { view: 0, edit: 0, delete: 0, export: 0, import: 0 },
101→    "system.users": { view: 0, edit: 0, delete: 0, export: 0, import: 0 },
102→    "system.permissions": { view: 0, edit: 0, delete: 0, export: 0, import: 0 },
103→    etc: { view: 0, edit: 0, delete: 0, export: 0, import: 0 },
104→  };
105→  for (const [resource, actions] of Object.entries(deanPerms)) {
106→    for (const [action, allowed] of Object.entries(actions)) {
107→      insertPerm.run("DEAN", resource, action, allowed);
108→    }
109→  }
110→});
111→
112→seedAll();
113→console.log("4. 시드 권한 데이터 삽입 완료");
114→console.log("Migration complete: permissions table created, roles migrated, seed data inserted.");
115→db.close();
116→

