if (tableInfo?.sql?.includes("CHECK")) {
  // foreign_keys를 일시적으로 끄고 테이블을 재생성
  // users를 rename→recreate→drop 하면 user_sessions와 submission_data의 FK가
  // users_old를 가리키게 되므로, 이 두 테이블도 재생성하여 FK를 올바르게 맞춘다.
  db.pragma("foreign_keys = OFF");
  db.exec(`
    -- 1) users 테이블 재생성
    ALTER TABLE users RENAME TO users_old;
    CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL UNIQUE,
      password TEXT NOT NULL,
      role TEXT NOT NULL,
      department_code TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (department_code) REFERENCES departments (dept_code)
    );
    INSERT INTO users SELECT * FROM users_old;
    DROP TABLE users_old;

    -- 2) user_sessions 재생성 (FK → users)
    ALTER TABLE user_sessions RENAME TO user_sessions_old;
    CREATE TABLE user_sessions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      session_token TEXT NOT NULL UNIQUE,
      expires_at TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
    );
    INSERT INTO user_sessions SELECT * FROM user_sessions_old;
    DROP TABLE user_sessions_old;

    -- 3) submission_data 재생성 (FK → users, recruitment_requests)
    ALTER TABLE submission_data RENAME TO submission_data_old;
    CREATE TABLE submission_data (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      request_id INTEGER NOT NULL,
      submitted_by INTEGER NOT NULL,
      procedure_type TEXT NOT NULL,
      step_key TEXT NOT NULL,
      status_before TEXT NOT NULL,
      status_after TEXT,
      payload_json TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (request_id) REFERENCES recruitment_requests (id) ON DELETE CASCADE,
      FOREIGN KEY (submitted_by) REFERENCES users (id) ON DELETE CASCADE
    );
    INSERT INTO submission_data SELECT * FROM submission_data_old;
    DROP TABLE submission_data_old;
  `);
  db.pragma("foreign_keys = ON");
  console.log("2. users 테이블 CHECK 제약 제거 완료 (user_sessions, submission_data FK도 재생성)");
} else {
  console.log("2. users 테이블에 CHECK 제약 없음, 건너뜀");
}

